let workspaceLayout='list',workspaceSort='recent',selectedRichTask=null;const stateOrder=['آماده بررسی','نیازمند اصلاح','در حال انجام','تعریف‌شده','متوقف‌شده','بسته‌شده'];
const richIcons={list:'<path d="M8 6h12M8 12h12M8 18h12M3 6h1M3 12h1M3 18h1"/>',board:'<rect x="3" y="4" width="7" height="16" rx="1"/><rect x="14" y="4" width="7" height="11" rx="1"/>',file:'<path d="M13 3H6v18h12V8zM13 3v5h5M9 13h6M9 17h5"/>',chat:'<path d="M4 4h16v12H9l-5 4zM8 8h8M8 12h5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6M17 2v6M3 11h18"/>',check:'<path d="m5 12 4 4L19 6"/>',arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',filter:'<path d="M4 6h16M7 12h10M10 18h4"/>'};
function richIcon(name){return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${richIcons[name]||richIcons.list}</svg>`}
function taskCode(t){if(t.code)return t.code;let n=0;for(const c of t.id)n=(n*31+c.charCodeAt(0))>>>0;return 'DR-'+String(n%9000+1000)}
function updateTime(t){return t.reports?.at(-1)?.time||t.created}
function displayFileCount(t){return t.demoVersions?.reduce((n,v)=>n+v.files.length,0)||t.attachmentCount||0}
function taskTable(list,compact=false){if(!list.length)return empty('کاری با این فیلتر پیدا نشد. فیلتر را تغییر دهید یا کار جدیدی تعریف کنید.');return `<div class="table-wrap rich-table"><table><thead><tr><th>عنوان و شرح کار</th><th>مسئول</th><th>مهلت انجام</th><th>وضعیت</th></tr></thead><tbody>${list.map(t=>`<tr data-rich-task="${esc(t.id)}" class="${selectedRichTask===t.id?'selected-row':''}"><td><div class="rich-task-title"><span class="task-orbit ${statusClass(t.status)}">${t.status==='بسته‌شده'?richIcon('check'):''}</span><div><button class="task-title" data-task="${esc(t.id)}">${esc(t.title)}</button><div class="task-row-meta"><span dir="ltr">${taskCode(t)}</span><span>${esc(t.discipline||'کارهای پروژه')}</span>${t.demo?'<span class="demo-tag">نمونه</span>':t.sample?'<span class="demo-tag">نمونه قبلی</span>':''}${isCollaborator(t)?'<span class="collab-tag">همکاری شما</span>':''}<span class="row-signals">${displayFileCount(t)?richIcon('file')+num(displayFileCount(t)):''}${(t.reports||[]).length?richIcon('chat')+num(t.reports.filter(r=>r.type!=='event').length):''}</span></div></div></div></td><td>${person(t.owner)}${t.collaborators?.length?`<small class="table-collabs">+${num(t.collaborators.length)} همکار</small>`:''}</td><td><span class="due-date ${late(t)?'late':''}">${fmt(t.due)}</span>${late(t)?'<small class="late-label">عقب‌افتاده</small>':''}</td><td><button class="status-link" data-task="${esc(t.id)}" aria-label="وضعیت ${esc(t.title)}">${badge(t)}</button></td></tr>`).join('')}</tbody></table></div>`}
function renderTasks(){const scope=tasks.filter(t=>view==='all'||t.owner===me()||isCollaborator(t)||(manager()&&t.assignedBy===me()));const matches=scope.filter(t=>(!simpleQuery||(t.title+' '+t.description+' '+taskCode(t)).includes(simpleQuery))&&(!simpleOwner||t.owner===Number(simpleOwner))&&(simpleFilter==='all'?true:simpleFilter==='open'?t.status!=='بسته‌شده':simpleFilter==='myreview'?t.status==='آماده بررسی'&&t.assignedBy===me():simpleFilter==='late'?late(t):t.status===simpleFilter));matches.sort((a,b)=>workspaceSort==='due'?(a.due||'9999').localeCompare(b.due||'9999'):updateTime(b).localeCompare(updateTime(a)));const counters=[['all','همه کارها',scope.length],['در حال انجام','در حال انجام',scope.filter(t=>t.status==='در حال انجام').length],['آماده بررسی','منتظر بررسی',scope.filter(t=>t.status==='آماده بررسی').length],['late','عقب‌افتاده',scope.filter(late).length],['بسته‌شده','بسته‌شده',scope.filter(t=>t.status==='بسته‌شده').length]];const activePeople=[...new Set(scope.flatMap(t=>[t.owner,...(t.collaborators||[])])).values()].filter(i=>!members[i]?.legacy);$('#workspace').innerHTML=`<div class="workspace-overview"><div><span class="workspace-kicker">پروژه دارایی <span>／</span> شرکت سمندیس</span><h2>${view==='mine'?'فضای کار '+esc(people[me()]):'وضعیت کارهای پروژه'}</h2><p>فایل‌ها، گفت‌وگو و تأیید نهایی در پرونده هر کار</p></div><div class="team-stack">${activePeople.slice(0,5).map(i=>`<span class="avatar" title="${esc(people[i])}">${esc(people[i][0])}</span>`).join('')}<small>${num(activePeople.length)} نفر در پروژه</small></div></div><div class="workspace-demo-line"><span class="live-demo-dot"></span>نمونه تعاملی با داده‌های نمایشی · ذخیره در همین مرورگر · داده‌های قبلی شما محفوظ‌اند.${demoInstallError?'<b> فضای ذخیره مرورگر را بررسی کنید.</b>':''}</div><div class="workspace-filters">${counters.map(([key,label,n])=>`<button data-rich-filter="${key}" class="${simpleFilter===key?'selected':''}">${label}<b>${num(n)}</b></button>`).join('')}${manager()?`<button class="review-mine" data-rich-filter="myreview">برای تأیید من <b>${num(scope.filter(t=>t.status==='آماده بررسی'&&t.assignedBy===me()).length)}</b></button>`:''}</div><div class="workspace-toolbar"><div class="workspace-search">${richIcon('filter')}<input id="richSearch" aria-label="جست‌وجوی کار" placeholder="جست‌وجو در عنوان، شرح یا شناسه کار…" value="${esc(simpleQuery)}"></div><select id="richOwner" aria-label="مسئول کار"><option value="">همه مسئول‌ها</option>${[...new Set(scope.map(t=>t.owner))].map(i=>`<option value="${i}" ${simpleOwner===String(i)?'selected':''}>${esc(people[i])}</option>`).join('')}</select><select id="richSort" aria-label="مرتب‌سازی"><option value="recent" ${workspaceSort==='recent'?'selected':''}>آخرین فعالیت</option><option value="due" ${workspaceSort==='due'?'selected':''}>نزدیک‌ترین مهلت</option></select><div class="layout-switch"><button data-layout="list" class="${workspaceLayout==='list'?'selected':''}" aria-label="نمای فهرست">${richIcon('list')}</button><button data-layout="board" class="${workspaceLayout==='board'?'selected':''}" aria-label="نمای برد">${richIcon('board')}</button></div></div><div class="workspace-result-line"><span>${num(matches.length)} کار نمایش داده می‌شود</span><span>${workspaceLayout==='list'?'گروه‌بندی بر اساس وضعیت':'نمای برد بر اساس وضعیت'} · برای جزئیات، کار را انتخاب کنید</span></div>${matches.length?(workspaceLayout==='board'?renderRichBoard(matches):stateOrder.map(s=>{const group=matches.filter(t=>t.status===s);return group.length?`<details class="task-group ${statusClass(s)}" open><summary><span class="group-dot"></span>${s}<b>${num(group.length)}</b><span class="group-summary-note">${s==='آماده بررسی'?'ارسال‌شده و منتظر تأیید نهایی':s==='بسته‌شده'?'تأییدشده؛ نسخه‌ها و سوابق محفوظ':''}</span></summary>${taskTable(group)}</details>`:''}).join('')):empty('در این نما کاری پیدا نشد. «همه کارها» را انتخاب کنید.')}<div class="workspace-endnote">نمایش سابقه، به‌جای پاک‌کردن کارها · نسخه‌های قبلی در پرونده هر تسک باقی می‌مانند.</div>`;$('#workspace').querySelectorAll('[data-rich-filter]').forEach(b=>b.onclick=()=>{simpleFilter=b.dataset.richFilter;renderTasks()});$('#richSearch').oninput=e=>{const caret=e.target.selectionStart;simpleQuery=e.target.value;renderTasks();$('#richSearch').focus();$('#richSearch').setSelectionRange(caret,caret)};$('#richOwner').onchange=e=>{simpleOwner=e.target.value;renderTasks()};$('#richSort').onchange=e=>{workspaceSort=e.target.value;renderTasks()};$('#workspace').querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{workspaceLayout=b.dataset.layout;renderTasks()})}
function renderRichBoard(list){return `<div class="workspace-board">${stateOrder.map(s=>{const group=list.filter(t=>t.status===s);return `<section class="board-lane ${statusClass(s)}"><h3><span class="group-dot"></span>${s}<b>${num(group.length)}</b></h3>${group.map(t=>`<button class="board-task" data-task="${esc(t.id)}"><span class="board-code" dir="ltr">${taskCode(t)}</span><strong>${esc(t.title)}</strong><p>${esc(t.discipline||'کارهای پروژه')}${t.demo||t.sample?' · نمونه':''}</p><div class="board-task-footer"><span class="avatar" title="${esc(people[t.owner])}">${esc(people[t.owner]?.[0]||'؟')}</span><span class="${late(t)?'late':''}">${fmt(t.due)}</span><span class="board-files">${displayFileCount(t)?richIcon('file')+num(displayFileCount(t)):''}</span></div></button>`).join('')||'<div class="board-empty">کاری در این وضعیت نیست</div>'}</section>`}).join('')}</div>`}
const workflowDetail=detail;detail=async function(id){const t=tasks.find(t=>t.id===id);if(!t)return;const previousScroll=window.scrollY;selectedRichTask=id;try{await ensureDemoFiles(t)}catch{toast('پیوست‌های نمونه هنوز بارگذاری نشده‌اند؛ اتصال را بررسی کنید.')}if(selectedRichTask!==id)return;await workflowDetail(id);if(selectedRichTask!==id||!$('#details').open)return;const d=$('#details');if(window.matchMedia('(min-width: 1200px)').matches){document.body.classList.add('task-drawer-open');d.close();d.show()}$('#detailBody').insertAdjacentHTML('afterbegin',`<div class="drawer-context"><span dir="ltr">${taskCode(t)}</span><span>${esc(t.discipline||'پرونده کار')}</span>${t.demo||t.sample?'<small>سناریوی نمونه</small>':''}</div>`);const head=$('#detailBody .dialog-head');if(head)head.classList.add('drawer-title');const oldClose=$('#closeTask')?.onclick;if($('#closeTask'))$('#closeTask').onclick=()=>{document.body.classList.remove('task-drawer-open');selectedRichTask=null;oldClose?.();if(['mine','all'].includes(view))renderTasks()};d.oncancel=()=>{document.body.classList.remove('task-drawer-open');selectedRichTask=null};const allReports=$('#detailBody').querySelectorAll('.report-item');allReports.forEach((item,i)=>{const r=t.reports[i];if(r)item.insertAdjacentHTML('afterbegin',`<span class="comment-avatar avatar">${esc(people[r.person]?.[0]||'؟')}</span>`)});const form=$('#feedbackForm');if(form)form.insertAdjacentHTML('afterbegin',`<div class="reply-heading">${richIcon('chat')} ${manager()?'بازخورد شما به تیم':'گزارش و پاسخ شما'}</div>`);$('#detailBody').insertAdjacentHTML('beforeend','<button class="drawer-reply-jump" id="jumpToReply">'+richIcon('chat')+' نوشتن گزارش / بازخورد</button>');$('#jumpToReply').onclick=()=>{$('#feedbackForm').scrollIntoView({behavior:'smooth',block:'start'});$('#feedbackForm textarea').focus()};if(['mine','all'].includes(view))renderTasks();if(window.matchMedia('(min-width: 1200px)').matches)window.scrollTo({top:previousScroll,behavior:'auto'})};
const workflowRender=render;render=function(){document.body.classList.toggle('workspace-task-view',['mine','all'].includes(view));workflowRender();if(!$('#details').open)document.body.classList.remove('task-drawer-open');$('#subtitle').textContent=['mine','all'].includes(view)?'فضای مشترک پیگیری کارهای داخلی تیم':'شرکت سمندیس · پروژه دارایی';$('#demoInfoBadge')?.remove();if(view==='reports')$('#workspace').insertAdjacentHTML('afterbegin','<div class="workspace-demo-line" id="demoInfoBadge">داده‌های سناریوی نمونه در گزارش قابل مشاهده‌اند؛ این اعداد، ارزیابی واقعی کارکنان نیستند.</div>')};
const workflowNavigate=navigate;navigate=function(v){document.body.classList.remove('task-drawer-open');selectedRichTask=null;$('#details').close();workflowNavigate(v);window.scrollTo({top:0,behavior:'auto'});if(['mine','all'].includes(view)){simpleFilter='all';renderTasks()}};
document.addEventListener('click',e=>{const row=e.target.closest('tr[data-rich-task]');if(row&&!e.target.closest('button,a,input,select,summary'))detail(row.dataset.richTask)});$('#details').addEventListener('close',()=>{if(!$('#details').open)document.body.classList.remove('task-drawer-open')});
document.querySelectorAll('nav [data-view]').forEach(b=>{const span=b.querySelector('span');if(span)span.innerHTML=richIcon(b.dataset.view==='program'?'calendar':b.dataset.view==='mine'?'check':'list')});$('.identity').insertAdjacentHTML('afterend','<span class="product-workspace-label">فضای کار پروژه</span>');$('.sidebar-foot').insertAdjacentHTML('beforebegin',`<div class="sidebar-project-card"><span class="project-status-dot"></span><div><b>پروژه دارایی</b><small>شرکت سمندیس</small></div><span class="project-initial">${richIcon('calendar')}</span></div>`);$('#today').textContent=fmt(now());$('#person').addEventListener('change',()=>{document.body.classList.remove('task-drawer-open');selectedRichTask=null;simpleFilter='all';if(['mine','all'].includes(view))renderTasks()});view=manager()?'all':'mine';simpleFilter='all';render();
